3	namespace App\Http\Controllers\Api\Professional;
4	
5	use App\Http\Controllers\Api\ApiController;
6	use App\Http\Controllers\Concerns\ResolveCurrentProfessional;
7	use App\Http\Controllers\Concerns\ResolveCurrentSite;
8	use App\Http\Requests\Api\Professional\Documents\UpdateDocumentRequest;
9	use App\Http\Requests\Api\Professional\Documents\UploadDocumentRequest;
10	use App\Models\Core\Site\SiteMedia;
11	use App\Services\Cache\SiteCacheService;
12	use Illuminate\Http\JsonResponse;
13	use Illuminate\Http\Request;
14	use Illuminate\Support\Facades\DB;
15	use Illuminate\Support\Facades\Log;
16	use Illuminate\Support\Facades\Storage;
17	
18	// V2: Per-site document CRUD (PDF/JPG/PNG, 1 per site). Flat-replace
19	// semantics — a second upload soft-deletes the existing row and deletes
20	// its R2 bytes synchronously before creating the new row.
21	class ProfessionalDocumentController extends ApiController
22	{
23	    use ResolveCurrentProfessional;
24	    use ResolveCurrentSite;
25	
26	    public function index(Request $request): JsonResponse
27	    {
28	        $pro = $this->currentProfessional($request);
29	        $pro->loadMissing('site');
30	        $site = $this->currentSite($pro);
31	
32	        // Return the document regardless of is_active so draft docs surface in
33	        // the dashboard — the frontend publish toggle flips is_active directly.
34	        $media = SiteMedia::query()
35	            ->where('site_id', $site->id)
36	            ->where('pool', SiteMedia::POOL_DOCUMENTS)
37	            ->whereNull('deleted_at')
38	            ->first();
39	
40	        return $this->success([
41	            'document' => $media ? $this->buildDocumentPayload($media) : null,
42	        ]);
43	    }
44	
45	    public function store(UploadDocumentRequest $request): JsonResponse
46	    {
47	        $pro = $this->currentProfessional($request);
48	        $pro->loadMissing('site');
49	        $site = $this->currentSite($pro);
50	
51	        // Brand accounts are excluded per product spec — they have Shopify
52	        // for catalogue assets and don't get the generic document slot.
53	        if ($pro->professional_type === 'brand') {
54	            return $this->error('Documents section not available for brand accounts.', 403);
55	        }
56	
57	        // Double MIME-check via finfo — prevents Content-Type header spoofing
58	        // on top of the mimes: validation rule which trusts the client header.
59	        $file = $request->file('file');
60	        $actualMime = (new \finfo(FILEINFO_MIME_TYPE))->file($file->getRealPath());
61	        $allowed = ['application/pdf', 'image/jpeg', 'image/png'];
62	        if (! in_array($actualMime, $allowed, true)) {
63	            return $this->error('Document bytes do not match an accepted file type.', 415);
64	        }
65	
66	        $title = trim((string) $request->validated('title'));
67	        $caption = $this->normaliseOptionalString($request->validated('caption'));
68	        $originalFilename = substr((string) $file->getClientOriginalName(), 0, 255);
69	
70	        // Flat-replace: inside one transaction, soft-delete the existing row
71	        // (if any), create the new row, stream the file to R2, and set the path.
72	        // The old row's R2 bytes are deleted AFTER commit so a transaction
73	        // rollback doesn't leave an active row pointing at missing bytes.
74	        //
75	        // If the transaction closure throws AFTER we've streamed the new file
76	        // to R2, the uploaded bytes would be orphaned (row gone, file remains).
77	        // Track the new path and clean it up in the catch branch below.
78	        $previousPath = null;
79	        $newUploadedPath = null;
80	        try {
81	            $media = DB::transaction(function () use ($site, $pro, $file, $actualMime, $title, $caption, $originalFilename, &$previousPath, &$newUploadedPath) {
82	                if (DB::getDriverName() === 'pgsql') {
83	                    DB::select('select pg_advisory_xact_lock(hashtext(?))', ["site-documents:{$site->id}"]);
84	                }
85	
86	                // Flat-replace targets any non-deleted doc (including drafts)
87	                // so uploading a new file always takes over the single slot.
88	                $existing = SiteMedia::query()
89	                    ->where('site_id', $site->id)
90	                    ->where('pool', SiteMedia::POOL_DOCUMENTS)
91	                    ->whereNull('deleted_at')
92	                    ->first();
93	
94	                if ($existing) {
95	                    // Capture the path for post-commit R2 cleanup.
96	                    $previousPath = (string) $existing->path;
97	                    // Suppress the old row's `deleted` observer event during
98	                    // flat-replace — the new row's `saved` event a few lines
99	                    // below will trigger section-visibility reevaluation once.
100	                    // Without this, both events fire post-commit and do the
101	                    // same DB read + check in sequence (wasted work).
102	                    SiteMedia::withoutEvents(function () use ($existing): void {
103	                        $existing->delete();
104	                    });
105	                }
106	
107	                // Extension is derived from the actual MIME — never from the
108	                // client-supplied filename (spoofable).
109	                $ext = match ($actualMime) {
110	                    'application/pdf' => 'pdf',
111	                    'image/jpeg' => 'jpg',
112	                    'image/png' => 'png',
113	                };
114	
115	                $media = SiteMedia::create([
116	                    'site_id' => $site->id,
117	                    'pool' => SiteMedia::POOL_DOCUMENTS,
118	                    'path' => '',
119	                    'alt_text' => $title,
120	                    'caption' => $caption,
121	                    'sort_order' => 0,
122	                    'is_active' => true,
123	                    'media_type' => SiteMedia::MEDIA_TYPE_DOCUMENT,
124	                    'processing_state' => SiteMedia::PROCESSING_STATE_READY,
125	                    'original_mime' => $actualMime,
126	                    'original_filename' => $originalFilename,
127	                    'original_size_bytes' => $file->getSize(),
128	                ]);
129	
130	                // Stream to R2 (not in-memory) — matches the video upload path
131	                // so 10 MB PDFs don't peg worker memory.
132	                $mediaDisk = config('sidest.media_disk');
133	                $path = "documents/{$pro->id}/{$media->id}/original.{$ext}";
134	                $stream = fopen($file->getRealPath(), 'rb');
135	                Storage::disk($mediaDisk)->put($path, $stream, 'public');
136	                if (is_resource($stream)) {
137	                    fclose($stream);
138	                }
139	                $newUploadedPath = $path;
140	
141	                $media->update(['path' => $path]);
142	
143	                return $media;
144	            });
145	        } catch (\Throwable $e) {
146	            // Transaction failed after the R2 put succeeded — clean up the
147	            // orphaned bytes so we don't leak storage on retries.
148	            if ($newUploadedPath !== null) {
149	                try {
150	                    Storage::disk(config('sidest.media_disk'))->delete($newUploadedPath);
151	                } catch (\Throwable $cleanupError) {
152	                    Log::warning('Failed to clean up orphaned document R2 object after transaction failure', [
153	                        'path' => $newUploadedPath,
154	                        'error' => $cleanupError->getMessage(),
155	                    ]);
156	                }
157	            }
158	            throw $e;
159	        }
160	
161	        // Post-commit: delete old R2 bytes. Safe to run outside the txn because
162	        // the old row is already soft-deleted (so no reader will try to fetch
163	        // the old path), and if this delete fails we just leak bytes — not a
164	        // correctness issue. If the transaction had rolled back, $previousPath
165	        // would stay null and this is a no-op.
166	        if ($previousPath !== null && $previousPath !== '') {
167	            try {
168	                Storage::disk(config('sidest.media_disk'))->delete($previousPath);
169	            } catch (\Throwable $e) {
170	                Log::warning('Failed to delete previous document R2 object after commit', [
171	                    'path' => $previousPath,
172	                    'error' => $e->getMessage(),
173	                ]);
174	            }
175	        }
176	
177	        app(SiteCacheService::class)->invalidateSite($site);
178	
179	        return $this->success(['document' => $this->buildDocumentPayload($media)], 201);
180	    }
181	
182	    /**
183	     * Edit document title and/or caption. isDirty-guarded so no-op PATCHes
184	     * don't churn the public-site cache.
185	     */
186	    public function update(UpdateDocumentRequest $request, SiteMedia $document): JsonResponse
187	    {
188	        $pro = $this->currentProfessional($request);
189	        $pro->loadMissing('site');
190	        $site = $this->currentSite($pro);
191	
192	        // Ownership check. Route model binding already 404s on soft-deleted rows
193	        // (SoftDeletes trait). We intentionally allow is_active = false so the
194	        // publish toggle can flip a draft document back to live.
195	        abort_unless(
196	            $document->site_id === $site->id
197	            && $document->pool === SiteMedia::POOL_DOCUMENTS,
198	            404
199	        );
200	
201	        $data = $request->validated();
202	        $update = [];
203	
204	        if (array_key_exists('title', $data)) {
205	            $update['alt_text'] = $this->normaliseOptionalString($data['title']);
206	        }
207	
208	        if (array_key_exists('caption', $data)) {
209	            $update['caption'] = $this->normaliseOptionalString($data['caption']);
210	        }
211	
212	        // is_enabled maps to is_active — the publish toggle flips this directly.
213	        if (array_key_exists('is_enabled', $data)) {
214	            $update['is_active'] = (bool) $data['is_enabled'];
215	        }
216	
217	        $changed = false;
218	        if (! empty($update)) {
219	            $document->fill($update);
220	            if ($document->isDirty(['alt_text', 'caption', 'is_active'])) {
221	                $document->save();
222	                $changed = true;
223	            }
224	        }
225	
226	        if ($changed) {
227	            app(SiteCacheService::class)->invalidateSite($site);
228	        }
229	
230	        return $this->success(['document' => $this->buildDocumentPayload($document->fresh())]);
231	    }
232	
233	    /**
234	     * Soft-delete the row and synchronously delete the R2 bytes (no
235	     * versioning, so there's no archival value in keeping bytes around).
236	     */
237	    public function destroy(Request $request, SiteMedia $document): JsonResponse
238	    {
239	        $pro = $this->currentProfessional($request);
240	        $pro->loadMissing('site');
241	        $site = $this->currentSite($pro);
242	
243	        // Ownership check — allows deleting draft (is_active = false) docs too.
244	        // Route model binding already 404s on soft-deleted rows.
245	        abort_unless(
246	            $document->site_id === $site->id
247	            && $document->pool === SiteMedia::POOL_DOCUMENTS,
248	            404
249	        );
250	
251	        try {
252	            Storage::disk(config('sidest.media_disk'))->delete((string) $document->path);
253	        } catch (\Throwable $e) {
254	            Log::warning('Failed to delete document R2 object on destroy', [
255	                'media_id' => $document->id,
256	                'path' => $document->path,
257	                'error' => $e->getMessage(),
258	            ]);
259	        }
260	
261	        $document->delete();
262	
263	        app(SiteCacheService::class)->invalidateSite($site);
264	
265	        return $this->success(['deleted' => true]);
266	    }
267	
268	    /**
269	     * @return array{id: string, title: string|null, caption: string|null, is_enabled: bool, original_mime: string|null, original_size_bytes: int|null, original_filename: string|null, preview_url: string, download_url: string, created_at: mixed, updated_at: mixed}
270	     */
271	    private function buildDocumentPayload(SiteMedia $media): array
272	    {
273	        $mediaDisk = config('sidest.media_disk');
274	        $previewUrl = Storage::disk($mediaDisk)->url((string) $media->path);
275	
276	        return [
277	            'id' => $media->id,
278	            'title' => $media->alt_text,
279	            'caption' => $media->caption,
280	            // is_enabled maps to is_active — the publish toggle reads and writes this.
281	            'is_enabled' => (bool) $media->is_active,
282	            'original_mime' => $media->original_mime,
283	            'original_size_bytes' => $media->original_size_bytes,
284	            'original_filename' => $media->original_filename,
285	            'preview_url' => $previewUrl,
286	            'download_url' => '/api/public/documents/'.$media->id.'/download',
287	            'created_at' => $media->created_at,
288	            'updated_at' => $media->updated_at,
289	        ];
290	    }
291	
292	    /**
293	     * Trim; coerce empty/whitespace-only strings to NULL so NULL and ""
294	     * mean the same thing at rest.
295	     */
296	    private function normaliseOptionalString(?string $raw): ?string
297	    {
298	        if ($raw === null) {
299	            return null;
300	        }
301	
302	        $trimmed = trim($raw);
303	
304	        return $trimmed === '' ? null : $trimmed;
305	    }
306	}
